function rollForwardIfPast(month, day) { const current = dubaiNowParts(); let year = current.year; let candidate = `${year}-${month}-${pad(day)}`; if (candidate < todayISO()) candidate = `${year + 1}-${month}-${pad(day)}`; return candidate; }
