  m = lower.match(/^(?:[a-zа-яё]+day\s+|(?:в|во)\s+)?(\d{1,2})\s+([a-zа-яё]+)$/i); if (m && MONTHS[m[2]]) return rollForwardIfPast(MONTHS[m[2]], m[1]);
  m = lower.match(/^(?:[a-zа-яё]+day\s+|(?:в|во)\s+)?([a-zа-яё]+)\s+(\d{1,2})$/i); if (m && MONTHS[m[1]]) return rollForwardIfPast(MONTHS[m[1]], m[2]);
  throw new Error(`Cannot parse date: ${dateText}`);
}
function normalizeTimeHour(h) { return h >= 1 && h <= 9 ? h + 12 : h; }
