const booking = $('Parse Booking Details').first().json;
const events = $('Get Calendar Events').all().map(item => item.json);

const bufferMinutes = 15;
const durationMinutes = booking.duration_minutes || 60;

// буфер уже включён в создаваемое событие
const totalMinutes = durationMinutes + bufferMinutes;

function timeToMinutes(time) {
  const [h, m] = String(time).split(':').map(Number);
  return h * 60 + m;
}

function eventTimeToMinutes(value, boundary) {
  if (!value) return null;
  if (!String(value).includes('T')) return boundary === 'end' ? 1440 : 0;
  const match = String(value).match(/T(\d{2}):(\d{2})/);
  if (!match) return null;
  return Number(match[1]) * 60 + Number(match[2]);
}

function overlaps(startA, endA, startB, endB) {
  return startA < endB && endA > startB;
}

const bookingStart = timeToMinutes(booking.time);
const bookingEnd = bookingStart + totalMinutes;

let hasConflict = false;

for (const event of events) {
  if (!event.start || !event.end) continue;

  const eventStartRaw = event.start.dateTime || event.start.date;
  const eventEndRaw = event.end.dateTime || event.end.date;

  const eventStart = eventTimeToMinutes(eventStartRaw, 'start');
  const eventEnd = eventTimeToMinutes(eventEndRaw, 'end');

  if (eventStart === null || eventEnd === null) continue;

  // событие уже включает буфер
  const blockedStart = eventStart;
  const blockedEnd = eventEnd;

  if (
    overlaps(
      bookingStart,
      bookingEnd,
      blockedStart,
      blockedEnd
    )
  ) {
    hasConflict = true;
    break;
  }
}

return [
  {
    json: {
      ...booking,
      hasConflict
    }
  }
];

