function normalizeTime(value) {
  const raw = String(value || '').trim().toLowerCase().replace(/\s+/g, ' ');
  const hm = raw.match(/\b(\d{1,2})[:.](\d{2})\s*(am|pm)?\b/i);
  if (hm) {
    let hour = Number(hm[1]);
    const minute = Number(hm[2]);
    const meridiem = hm[3] ? hm[3].toLowerCase() : '';
    if (meridiem === 'pm' && hour < 12) hour += 12;
    if (meridiem === 'am' && hour === 12) hour = 0;
    if (hour >= 0 && hour <= 23 && minute >= 0 && minute <= 59) {
      return String(hour).padStart(2, '0') + ':' + String(minute).padStart(2, '0');
    }
  }
  const hOnly = raw.match(/\b(\d{1,2})\s*(am|pm)\b/i);
  if (hOnly) {
    let hour = Number(hOnly[1]);
    const meridiem = hOnly[2].toLowerCase();
    if (meridiem === 'pm' && hour < 12) hour += 12;
    if (meridiem === 'am' && hour === 12) hour = 0;
    if (hour >= 0 && hour <= 23) return String(hour).padStart(2, '0') + ':00';
  }
  return '';
}

