let client = {}; try { client = $('Get or Create Client').first().json.client || {}; } catch(e) { client = {}; }
let normalized = {}; try { normalized = $('Normalize Telegram Input').first().json || {}; } catch(e) { normalized = {}; }
let telegram = {}; try { telegram = $('Telegram Trigger').first().json || {}; } catch(e) { telegram = {}; }
const rawText = String(normalized.text || telegram.message?.text || $json.text || '').trim();
const chatId = String(normalized.chat_id || normalized.recipient_id || telegram.message?.chat?.id || telegram.message?.from?.id || '').trim();
const fromId = String(normalized.sender_id || telegram.message?.from?.id || '').trim();
const clientId = String(client.client_id || '').trim();
const pending = $json.saved_pending || {};
function pad(n){ return String(n).padStart(2,'0'); }
function norm(v){ return String(v || '').toLowerCase().normalize('NFKD').replace(/[^\p{L}\p{N}]+/gu,' ').trim(); }
function field(desc,label){ const wanted=norm(label); for (const line of String(desc||'').split(/\r?\n/)) { const i=line.indexOf(':'); if (i<0) continue; if (norm(line.slice(0,i))===wanted) return line.slice(i+1).trim(); } return ''; }
function summaryParts(summary){ const parts=String(summary||'').split(' - '); return { service:(parts[0]||'').trim(), client:parts.slice(1).join(' - ').trim() }; }
function hasIdentityMatch(e){ const d=e.description||''; const ids=[field(d,'Telegram ID'), field(d,'Channel User ID'), field(d,'Chat ID')].map(String); const requested=[chatId, fromId].filter(Boolean); const clientField=field(d,'Client ID'); return requested.some(id=>ids.includes(id)) || (clientId && clientField === clientId); }
function eventName(e){ return field(e.description,'Client') || summaryParts(e.summary).client || ''; }
function eventService(e){ return field(e.description,'Service') || summaryParts(e.summary).service || ''; }
function eventDate(e){ return String(e.start?.dateTime||'').slice(0,10); }
function eventTime(e){ const m=String(e.start?.dateTime||'').match(/T(\d{2}):(\d{2})/); return m ? m[1]+':'+m[2] : ''; }
function prettyDate(iso){ const [y,m,d]=String(iso||'').split('-'); const names={ '01':'January','02':'February','03':'March','04':'April','05':'May','06':'June','07':'July','08':'August','09':'September','10':'October','11':'November','12':'December' }; return d ? Number(d)+' '+(names[m]||m)+' '+y : iso; }
function todayDubai(){ const p=new Intl.DateTimeFormat('en-CA',{ timeZone:'Asia/Dubai', year:'numeric', month:'2-digit', day:'2-digit'}).formatToParts(new Date()).reduce((a,p)=>{a[p.type]=p.value; return a;},{}); return p.year+'-'+p.month+'-'+p.day; }
function addDaysISO(iso,days){ const d=new Date(iso+'T00:00:00Z'); d.setUTCDate(d.getUTCDate()+days); return d.toISOString().slice(0,10); }
function parseDateIn(text){ const s=String(text||'').toLowerCase(); if(/\btomorrow\b/.test(s)) return addDaysISO(todayDubai(),1); if(/\btoday\b/.test(s)) return todayDubai(); const m=s.match(/\b(\d{4}-\d{1,2}-\d{1,2})\b/); return m ? m[1] : ''; }
function parseTimeIn(text){ const all=[...String(text||'').matchAll(/\b(\d{1,2})(?::(\d{2}))?\s*(am|pm)?\b/gi)]; if(!all.length) return ''; const m=all[all.length-1]; let h=Number(m[1]); const min=Number(m[2]||0); const ap=(m[3]||'').toLowerCase(); if(ap==='pm'&&h<12)h+=12; if(ap==='am'&&h===12)h=0; if(h>=1&&h<=9&&!ap)h+=12; if(h>23||min>59)return ''; return pad(h)+':'+pad(min)+':00'; }
function extractName(text){ const m=String(text||'').match(/\b(?:my name is|name is|for)\s+([A-Z][\p{L}'-]*(?:\s+[A-Z][\p{L}'-]*)?)/iu); return m ? m[1].trim() : ''; }
function extractService(text){ const s=String(text||'').toLowerCase(); const services=['gel manicure','gel pedicure','manicure','pedicure','haircut','massage','facial']; return services.find(x=>s.includes(x)) || ''; }
const targetPart = (String(rawText).match(/\b(?:to|на)\s+(.+)$/i)||[])[1] || rawText;
const newDate = pending.new_date || parseDateIn(targetPart);
const newTime = pending.new_time || parseTimeIn(targetPart);
const requestedName = extractName(rawText);
const requestedService = extractService(rawText);
let matches = events.filter(e => hasIdentityMatch(e));
if (requestedName) matches = matches.filter(e => norm(eventName(e)) === norm(requestedName));
if (requestedService) matches = matches.filter(e => norm(eventService(e)) === norm(requestedService));
matches.sort((a,b)=>String(a.start?.dateTime||'').localeCompare(String(b.start?.dateTime||'')));
const recipient_id = chatId;
if (!newTime) return [{ json:{ ...$json, auto_reschedule_ready:false, channel:'telegram', recipient_id, message_text:'Please provide your name, current appointment date/time and new preferred date/time.' } }];
if (matches.length === 1) {
  const e=matches[0]; const name=eventName(e) || client.preferred_name || client.first_name || 'client'; const service=eventService(e) || ''; const currentDate=eventDate(e); const currentTime=eventTime(e); const finalNewDate=newDate || currentDate;
  const output=['RESCHEDULE DETAILS','Name: '+name,'Current Date: '+currentDate,'Current Time: '+currentTime,'New Date: '+finalNewDate,'New Time: '+newTime.slice(0,5)].join('\n');
  return [{ json:{ ...$json, auto_reschedule_ready:true, output, name, service, current_date:currentDate, current_time:currentTime+':00', new_date:finalNewDate, new_time:newTime, recipient_id } }];
}
if (matches.length > 1) {
  const lines=matches.slice(0,5).map(e=>'- '+(eventService(e)||'appointment')+' for '+(eventName(e)||'client')+' on '+prettyDate(eventDate(e))+' at '+eventTime(e));
  return [{ json:{ ...$json, auto_reschedule_ready:false, channel:'telegram', recipient_id, message_text:'I found multiple upcoming appointments. Please send which one to reschedule by date and time:\n\n'+lines.join('\n') } }];
}
return [{ json:{ ...$json, auto_reschedule_ready:false, channel:'telegram', recipient_id, message_text:'Please provide your name, current appointment date and time so I can find the appointment to reschedule.' } }];

const store = $getWorkflowStaticData('global');
store.handoff_store = store.handoff_store || {};
store.pending_booking = store.pending_booking || {};
store.pending_reschedule = store.pending_reschedule || {};
let normalized = {}; try { normalized = $('Normalize Telegram Input').first().json || {}; } catch (e) { normalized = {}; }
let telegram = {}; try { telegram = $('Telegram Trigger').first().json || {}; } catch (e) { telegram = {}; }
const msg = telegram.message || telegram.edited_message || $json.message || {};
const clientChatId = String($json.chat_id || $json.recipient_id || normalized.chat_id || normalized.recipient_id || msg.chat?.id || msg.from?.id || '').trim();
const adminChatId = String($json.config?.admin_default_chat_id || $('Salon Config').first().json.config?.admin_default_chat_id || '').trim();
const key = 'telegram:' + clientChatId;
const existing = store.handoff_store[key] || {};
const nowIso = new Date().toISOString();
delete store.pending_booking['booking:' + clientChatId];
delete store.pending_reschedule['reschedule:' + clientChatId];
store.handoff_store[key] = {
  ...existing,
  human_takeover: true,
  assigned_admin_chat_id: adminChatId,
  client_chat_id: clientChatId,
  takeover_started_at: nowIso,
  released_at: '',
  created_at: existing.created_at || nowIso,
  updated_at: nowIso
};
const clientName = msg.from?.first_name || msg.from?.username || $json.sender_first_name || normalized.sender_first_name || 'Unknown';
const text = String($json.text || $json.raw_text || normalized.text || msg.text || '').trim();
const adminMessage = [
  'HUMAN HANDOFF REQUEST',
  '',
  'Client Telegram name: ' + clientName,
  'Telegram ID: ' + clientChatId,
  '',
  'Client message:',
  text,
  '',
  'Use:',
  '/reply ' + clientChatId + ' your message',
  '/release ' + clientChatId
].join('\n');
return [{ json: { ...$json, channel: 'handoff_admin', target_type: 'admin', admin_chat_id: adminChatId, message_text: adminMessage, client_chat_id: clientChatId, recipient_id: clientChatId, handoff_key: key, isHumanTakeover: true } }];
